import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import type { EngagementLikerProfile } from "../types";
import { resolveLocale } from "../lib/format-count";

/** Pixels the mouse must move before a press becomes a drag (a smaller move is a click). */
const DRAG_THRESHOLD_PX = 4;

/** Pointer-event drag-to-scroll for the likers strip (desktop). Touch devices get
 * native swipe via `touch-action: pan-x`. */
function useDragScroll() {
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const stateRef = useRef<{
    down: boolean;
    dragging: boolean;
    startX: number;
    startScroll: number;
    pointerId: number | null;
  }>({
    down: false,
    dragging: false,
    startX: 0,
    startScroll: 0,
    pointerId: null,
  });

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== "mouse") return; // touch handled natively
    const el = scrollRef.current;
    if (!el) return;
    stateRef.current = {
      down: true,
      dragging: false,
      startX: e.clientX,
      startScroll: el.scrollLeft,
      pointerId: e.pointerId,
    };
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const s = stateRef.current;
    if (!s.down || s.pointerId !== e.pointerId) return;
    // The button was released outside the strip (no pointerup reached it): the press is over.
    if (e.buttons === 0) {
      s.down = false;
      s.pointerId = null;
      return;
    }
    const el = scrollRef.current;
    if (!el) return;
    const dx = e.clientX - s.startX;
    // Capture only once the pointer really drags: capturing on pointerdown retargeted the
    // click of a button inside the strip (the "+N" pill) to the strip, so a mouse click
    // on the pill did nothing (0.6.1).
    if (!s.dragging) {
      if (Math.abs(dx) < DRAG_THRESHOLD_PX) return;
      s.dragging = true;
      try {
        el.setPointerCapture(e.pointerId);
      } catch {
        // the pointer may already be gone
      }
      el.style.cursor = "grabbing";
    }
    el.scrollLeft = s.startScroll - dx;
  };

  const endDrag = (e: React.PointerEvent<HTMLDivElement>) => {
    const s = stateRef.current;
    if (!s.down) return;
    s.down = false;
    s.pointerId = null;
    const wasDragging = s.dragging;
    s.dragging = false;
    const el = scrollRef.current;
    if (el && wasDragging) {
      el.style.cursor = "";
      try {
        el.releasePointerCapture(e.pointerId);
      } catch {
        // pointer may already be released
      }
    }
  };

  return {
    scrollRef,
    onPointerDown,
    onPointerMove,
    onPointerUp: endDrag,
    onPointerCancel: endDrag,
  };
}

/** Every user-facing string of `LikersStrip`. Override per key via `labels`. */
export interface LikersStripLabels {
  heading: string;
  close: string;
  loading: string;
  /** Pill text AND accessible name when the total is withheld (`totalCount={null}`). */
  loadMore: string;
  moreAriaLabel: (count: number, formatted: string) => string;
  morePill: (formatted: string) => string;
}

export const defaultLikersStripLabels: LikersStripLabels = {
  heading: "Likes",
  close: "Hide",
  loading: "…",
  loadMore: "More",
  moreAriaLabel: (_, f) => `+${f} more`,
  morePill: (f) => `+${f}`,
};

export interface LikersStripProps {
  /** Total likes on the post (drives the "+N" pill). `null` = withheld: no number is shown anywhere. */
  totalCount: number | null;
  /**
   * Already-loaded likers. With `onLikersChange` the strip is controlled (shows exactly this
   * list). Without it, the prop is still shown on every render, plus anything the strip loaded.
   */
  likers?: EngagementLikerProfile[];
  /** Uncontrolled seed, read once. */
  defaultLikers?: EngagementLikerProfile[];
  /** Controlled mode: called with the prop list plus the newly loaded likers. */
  onLikersChange?: (next: EngagementLikerProfile[]) => void;
  /** Fetch more likers. */
  onLoadMore?: () => Promise<EngagementLikerProfile[]>;
  /** Whether more likers exist. Overrides the count-derived pill visibility. */
  hasMore?: boolean;
  /** Override any user-facing string. An `undefined` value keeps the default. */
  labels?: Partial<LikersStripLabels>;
  /** BCP-47 locale for number formatting and initials. Default "en". */
  locale?: string;
  /** Replaces the compact `Intl.NumberFormat` count formatter. */
  formatCount?: (n: number) => string;
  /** @deprecated Use `labels.heading`. */
  heading?: string;
  /** @deprecated Use `labels.moreAriaLabel`. `{count}` is replaced. */
  moreAriaLabelTemplate?: string;
  /** When provided, renders a Hide button next to the heading. */
  onClose?: () => void;
  /** @deprecated Use `labels.close`. */
  closeLabel?: string;
  className?: string;
}

function initials(name: string, locale: string): string {
  return (
    name
      .trim()
      .split(/\s+/)
      .map((p) => p[0]?.toLocaleUpperCase(locale) ?? "")
      .slice(0, 2)
      .join("") || "?"
  );
}

function dedupeById(list: EngagementLikerProfile[]): EngagementLikerProfile[] {
  const seen = new Set<string>();
  const out: EngagementLikerProfile[] = [];
  for (const u of list) {
    if (seen.has(u.id)) continue;
    seen.add(u.id);
    out.push(u);
  }
  return out;
}

function LikersStripInner({
  totalCount,
  likers,
  defaultLikers,
  onLikersChange,
  onLoadMore,
  hasMore,
  labels: labelsProp,
  locale: localeProp = "en",
  formatCount,
  heading,
  moreAriaLabelTemplate,
  onClose,
  closeLabel,
  className,
}: LikersStripProps) {
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const controlled = likers !== undefined && onLikersChange !== undefined;
  // Likers this strip loaded itself (and the uncontrolled seed, read once).
  const [own, setOwn] = useState<EngagementLikerProfile[]>(() => defaultLikers ?? []);
  const [isLoading, setIsLoading] = useState(false);
  const loadingRef = useRef(false);

  const latestLikers = useRef<EngagementLikerProfile[]>(likers ?? []);
  useEffect(() => {
    latestLikers.current = likers ?? [];
  }, [likers]);

  const shown = useMemo(
    () => (controlled ? likers : dedupeById([...(likers ?? []), ...own])),
    [controlled, likers, own],
  );

  const numberFormat = useMemo(
    () => new Intl.NumberFormat(locale, { notation: "compact" }),
    [locale],
  );
  const format = formatCount ?? numberFormat.format;

  const labels = useMemo<LikersStripLabels>(() => {
    const merged: LikersStripLabels = {
      ...defaultLikersStripLabels,
      heading: heading ?? defaultLikersStripLabels.heading,
      close: closeLabel ?? defaultLikersStripLabels.close,
    };
    if (moreAriaLabelTemplate !== undefined) {
      const template = moreAriaLabelTemplate;
      merged.moreAriaLabel = (_, formatted) =>
        // template-ok: deprecated alias moreAriaLabelTemplate, kept for existing callers (post-card stopped passing it in 0.6.0)
        template.replace("{count}", formatted);
    }
    if (labelsProp) {
      for (const key of Object.keys(labelsProp) as (keyof LikersStripLabels)[]) {
        const value = labelsProp[key];
        if (value !== undefined) (merged as unknown as Record<string, unknown>)[key] = value;
      }
    }
    return merged;
  }, [labelsProp, heading, closeLabel, moreAriaLabelTemplate]);

  const remaining = totalCount === null ? null : Math.max(0, totalCount - shown.length);
  const pillVisible =
    Boolean(onLoadMore) && (hasMore ?? (remaining === null ? true : remaining > 0));
  const pending = remaining !== null && remaining > 0 ? remaining : null;
  const {
    scrollRef,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onPointerCancel,
  } = useDragScroll();

  const handleLoadMore = useCallback(async () => {
    if (!onLoadMore || loadingRef.current) return;
    loadingRef.current = true;
    setIsLoading(true);
    try {
      const next = await onLoadMore();
      if (onLikersChange && likers !== undefined) {
        onLikersChange([...latestLikers.current, ...next]);
      } else {
        setOwn((prev) => [...prev, ...next]);
      }
    } catch {
      // A failed load leaves the list unchanged; the button re-enables for a retry.
    } finally {
      loadingRef.current = false;
      setIsLoading(false);
    }
  }, [onLoadMore, onLikersChange, likers]);

  const pillText = isLoading
    ? labels.loading
    : pending !== null
      ? // The full count (compact), so the visible text is part of the accessible name
        // (WCAG 2.5.3) — it was capped at "+99" while the name said "+379 more" (0.6.1).
        labels.morePill(format(pending))
      : labels.loadMore;
  const pillAria = pending !== null
    ? labels.moreAriaLabel(pending, format(pending))
    : labels.loadMore;

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <div className="flex items-center justify-between gap-2">
        <span className="text-sm font-semibold">{labels.heading}</span>
        {onClose ? (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-7 px-2 text-xs"
          >
            {labels.close}
          </Button>
        ) : null}
      </div>
      <div
        ref={scrollRef}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerCancel}
        style={{ touchAction: "pan-x" }}
        className="flex cursor-grab select-none items-stretch gap-3 overflow-x-auto pb-1 [scrollbar-width:thin]"
        role="list"
      >
        {shown.map((user) => (
          <div
            key={user.id}
            role="listitem"
            className="flex w-16 shrink-0 flex-col items-center gap-1 sm:w-20"
          >
            <Avatar className="h-10 w-10 sm:h-12 sm:w-12">
              {user.avatar ? <AvatarImage src={user.avatar} alt="" /> : null}
              <AvatarFallback>{initials(user.name, locale)}</AvatarFallback>
            </Avatar>
            {/* Fixed-height name+username slot — keeps every column the same total height
                so the strip looks symmetric regardless of which users have a username. */}
            <div className="flex h-8 w-full flex-col justify-start text-center">
              <span className="truncate text-xs font-medium leading-tight">
                {user.name.split(" ")[0]}
              </span>
              <span className="truncate text-[10px] leading-tight text-muted-foreground">
                {user.username ? `@${user.username}` : " "}
              </span>
            </div>
          </div>
        ))}
        {pillVisible ? (
          <div role="listitem" className="flex w-16 shrink-0 flex-col items-center gap-1 sm:w-20">
            <Button
              type="button"
              variant="outline"
              onClick={() => {
                void handleLoadMore();
              }}
              disabled={isLoading}
              aria-busy={isLoading ? "true" : undefined}
              aria-label={pillAria}
              className="h-11 w-11 shrink-0 rounded-full p-0 text-xs font-semibold sm:h-12 sm:w-12"
            >
              {pillText}
            </Button>
            <div className="h-8" aria-hidden="true" />
          </div>
        ) : null}
      </div>
    </div>
  );
}

export const LikersStrip = memo(LikersStripInner);
LikersStrip.displayName = "LikersStrip";

"use client";

import { memo, useMemo, useRef, useState } from "react";
import { Search, Send } from "lucide-react";
import { cn } from "@/lib/utils";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import type { EngagementLikerProfile } from "../types";
import { resolveLocale } from "../lib/format-count";

/** Every user-facing string of `ShareMenu`. Override per key via `labels`. */
export interface ShareMenuLabels {
  heading: string;
  searchPlaceholder: string;
  /** Accessible name of the search input. */
  searchLabel: string;
  empty: string;
  close: string;
}

export const defaultShareMenuLabels: ShareMenuLabels = {
  heading: "Share with…",
  searchPlaceholder: "Search people…",
  searchLabel: "Search people",
  empty: "No matches.",
  close: "Hide",
};

export interface ShareMenuProps {
  /** Pre-loaded recent / suggested users for sharing. */
  users: EngagementLikerProfile[];
  /** Optional async search — called on every input change with the query. The latest request
   * wins; a rejection falls back to filtering `users` locally. If omitted, the panel filters
   * `users` locally by name/username. */
  onSearch?: (query: string) => Promise<EngagementLikerProfile[]>;
  /** Fired when the user selects someone to share with. */
  onShareTo: (user: EngagementLikerProfile) => void;
  /** Override any user-facing string. An `undefined` value keeps the default. */
  labels?: Partial<ShareMenuLabels>;
  /** BCP-47 locale for case folding and initials. Default "en". */
  locale?: string;
  /** @deprecated Use `labels.heading`. */
  heading?: string;
  /** @deprecated Use `labels.searchPlaceholder`. */
  searchPlaceholder?: string;
  /** @deprecated Use `labels.empty`. */
  emptyLabel?: string;
  /** When provided, renders a Hide button next to the heading. */
  onClose?: () => void;
  /** @deprecated Use `labels.close`. */
  closeLabel?: string;
  className?: string;
}

function initials(name: string, locale: string): string {
  return (
    name
      .trim()
      .split(/\s+/)
      .map((p) => p[0]?.toLocaleUpperCase(locale) ?? "")
      .slice(0, 2)
      .join("") || "?"
  );
}

function ShareMenuInner({
  users,
  onSearch,
  onShareTo,
  labels: labelsProp,
  locale: localeProp = "en",
  heading,
  searchPlaceholder,
  emptyLabel,
  onClose,
  closeLabel,
  className,
}: ShareMenuProps) {
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const [query, setQuery] = useState("");
  const [searchResults, setSearchResults] = useState<EngagementLikerProfile[] | null>(
    null,
  );
  const requestSeq = useRef(0);

  const labels = useMemo<ShareMenuLabels>(() => {
    const merged: ShareMenuLabels = {
      ...defaultShareMenuLabels,
      heading: heading ?? defaultShareMenuLabels.heading,
      searchPlaceholder: searchPlaceholder ?? defaultShareMenuLabels.searchPlaceholder,
      empty: emptyLabel ?? defaultShareMenuLabels.empty,
      close: closeLabel ?? defaultShareMenuLabels.close,
    };
    if (labelsProp) {
      for (const key of Object.keys(labelsProp) as (keyof ShareMenuLabels)[]) {
        const value = labelsProp[key];
        if (value !== undefined) merged[key] = value;
      }
    }
    return merged;
  }, [labelsProp, heading, searchPlaceholder, emptyLabel, closeLabel]);

  const visibleUsers = useMemo<EngagementLikerProfile[]>(() => {
    if (searchResults !== null) return searchResults;
    const q = query.trim().toLocaleLowerCase(locale);
    if (!q) return users;
    return users.filter(
      (u) =>
        u.name.toLocaleLowerCase(locale).includes(q) ||
        (u.username ? u.username.toLocaleLowerCase(locale).includes(q) : false),
    );
  }, [searchResults, query, users, locale]);

  const handleQueryChange = async (next: string) => {
    setQuery(next);
    const seq = ++requestSeq.current;
    if (!onSearch || !next.trim()) {
      setSearchResults(null);
      return;
    }
    try {
      const results = await onSearch(next);
      if (seq !== requestSeq.current) return;
      setSearchResults(results);
    } catch {
      // Only the latest request may fall back; an older failure is irrelevant.
      if (seq === requestSeq.current) setSearchResults(null);
    }
  };

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <div className="flex items-center justify-between gap-2">
        <span className="text-sm font-semibold">{labels.heading}</span>
        {onClose ? (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={onClose}
            className="h-7 px-2 text-xs"
          >
            {labels.close}
          </Button>
        ) : null}
      </div>
      <div className="relative">
        <Search
          aria-hidden="true"
          className="pointer-events-none absolute start-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground"
        />
        <Input
          value={query}
          onChange={(e) => {
            void handleQueryChange(e.target.value);
          }}
          placeholder={labels.searchPlaceholder}
          aria-label={labels.searchLabel}
          className="h-9 ps-8"
        />
      </div>
      {visibleUsers.length === 0 ? (
        <div
          className="px-3 py-6 text-center text-xs text-muted-foreground"
          role="status"
        >
          {labels.empty}
        </div>
      ) : (
        <ul className="-mx-1 max-h-64 overflow-y-auto" role="list">
          {visibleUsers.map((user) => (
            <li key={user.id}>
              <button
                type="button"
                onClick={() => onShareTo(user)}
                className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-start motion-safe:transition-colors hover:bg-muted focus:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <Avatar className="h-8 w-8 shrink-0">
                  {user.avatar ? (
                    <AvatarImage src={user.avatar} alt="" />
                  ) : null}
                  <AvatarFallback className="text-[10px]">
                    {initials(user.name, locale)}
                  </AvatarFallback>
                </Avatar>
                <div className="min-w-0 flex-1">
                  <div className="truncate text-sm font-medium">
                    {user.name}
                  </div>
                  {user.username ? (
                    <div className="truncate text-xs text-muted-foreground">
                      @{user.username}
                    </div>
                  ) : null}
                </div>
                <Send
                  aria-hidden="true"
                  className="h-4 w-4 shrink-0 text-muted-foreground"
                />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export const ShareMenu = memo(ShareMenuInner);
ShareMenu.displayName = "ShareMenu";

"use client";

import { memo, useCallback, useRef } from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import type {
  EngagementCount,
  EngagementReactionKind,
  ResolvedEngagementBarLabels,
} from "../types";
import { useDirection, type Direction } from "../hooks/use-direction";
import { useActionName } from "../lib/action-name";

export interface ReactionPickerProps {
  /** Ordered kind catalog. Picker renders one button per kind in order. */
  kinds: EngagementReactionKind[];
  /**
   * Shown counts per kind (`EngagementState.reactionCounts` from the bar). The picker reads this
   * map, not `kinds[i].count`. A missing or `null` entry renders no number.
   */
  mergedCounts: Record<string, EngagementCount>;
  /** Viewer's currently-selected kind key, or null. Highlights matching kind. */
  viewerReaction: string | null;
  /** Fires when viewer picks a kind, or null via the Remove button. */
  onSelect: (kind: string | null) => void;
  /** Required, fully-resolved labels (no undefined). */
  labels: ResolvedEngagementBarLabels;
  /** Count formatter. Default `String`. The bar passes its locale-aware formatter. */
  format?: (n: number) => string;
  /**
   * Arrow-key direction: in `"rtl"`, → moves to the previous kind. Default: the picker's own
   * direction after mount. The picker usually renders in a portal — pass the host's direction.
   */
  dir?: Direction;
  className?: string;
}

function KindButton({
  kind,
  count,
  isSelected,
  format,
  buttonRef,
  onSelect,
  onKeyDown,
}: {
  kind: EngagementReactionKind;
  count: EngagementCount;
  isSelected: boolean;
  format: (n: number) => string;
  buttonRef: (el: HTMLButtonElement | null) => void;
  onSelect: () => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLButtonElement>) => void;
}) {
  const showCount = count !== null && count > 0;
  const name = useActionName(showCount);
  return (
    <button
      ref={buttonRef}
      type="button"
      aria-labelledby={name.labelledBy}
      aria-pressed={isSelected}
      onClick={onSelect}
      onKeyDown={onKeyDown}
      className={cn(
        "flex flex-col items-center gap-0.5 rounded-md px-2 py-1.5",
        "motion-safe:transition-transform motion-safe:hover:scale-125",
        "focus:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        isSelected && "bg-accent",
      )}
      style={kind.color ? { color: kind.color } : undefined}
    >
      <span aria-hidden="true" className="flex h-6 w-6 items-center justify-center">
        {kind.icon}
      </span>
      <span id={name.labelId} className="sr-only">
        {kind.label}
      </span>
      {showCount ? (
        <span
          id={name.countId}
          className="text-[10px] font-medium tabular-nums leading-none text-muted-foreground"
        >
          {format(count)}
        </span>
      ) : null}
    </button>
  );
}

function ReactionPickerInner({
  kinds,
  mergedCounts,
  viewerReaction,
  onSelect,
  labels,
  format = String,
  dir,
  className,
}: ReactionPickerProps) {
  const groupRef = useRef<HTMLDivElement | null>(null);
  const direction = useDirection(groupRef, dir);
  const buttonsRef = useRef<Array<HTMLButtonElement | null>>([]);
  const showRemove = viewerReaction !== null;
  const buttonCount = kinds.length + (showRemove ? 1 : 0);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>, index: number) => {
      const forward = direction === "rtl" ? "ArrowLeft" : "ArrowRight";
      const backward = direction === "rtl" ? "ArrowRight" : "ArrowLeft";
      let target: number | null = null;
      if (e.key === forward) target = (index + 1) % buttonCount;
      else if (e.key === backward) target = (index - 1 + buttonCount) % buttonCount;
      else if (e.key === "Home") target = 0;
      else if (e.key === "End") target = buttonCount - 1;
      if (target === null) return;
      e.preventDefault();
      buttonsRef.current[target]?.focus();
    },
    [buttonCount, direction],
  );

  return (
    <div
      ref={groupRef}
      role="group"
      aria-label={labels.reactionPickerLabel}
      className={cn("flex items-center gap-1 p-1", className)}
    >
      {kinds.map((kind, index) => (
        <KindButton
          key={kind.key}
          kind={kind}
          count={mergedCounts[kind.key] ?? null}
          isSelected={kind.key === viewerReaction}
          format={format}
          buttonRef={(el) => {
            buttonsRef.current[index] = el;
          }}
          onSelect={() => onSelect(kind.key)}
          onKeyDown={(e) => handleKeyDown(e, index)}
        />
      ))}
      {showRemove ? (
        <button
          ref={(el) => {
            buttonsRef.current[kinds.length] = el;
          }}
          type="button"
          aria-label={labels.removeReaction}
          onClick={() => onSelect(null)}
          onKeyDown={(e) => handleKeyDown(e, kinds.length)}
          className={cn(
            "flex h-9 w-9 items-center justify-center rounded-md text-muted-foreground",
            "motion-safe:transition-colors hover:bg-destructive/10 hover:text-destructive",
            "focus:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          )}
        >
          <X aria-hidden="true" className="h-4 w-4" />
        </button>
      ) : null}
    </div>
  );
}

export const ReactionPicker = memo(ReactionPickerInner);
ReactionPicker.displayName = "ReactionPicker";

"use client";

import { memo, useCallback, useEffect, useRef, useState } from "react";
import { Smile } from "lucide-react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import type {
  EngagementAction,
  EngagementBarVariant,
  EngagementState,
  ResolvedEngagementBarLabels,
} from "../types";
import type { Direction } from "../hooks/use-direction";
import { DISABLED_ACTION_CLASS, useActionName } from "../lib/action-name";
import { ReactionPicker } from "./reaction-picker";

const LONG_PRESS_MS = 350;
const POINTER_MOVE_TOLERANCE_SQ = 100; // (10px)^2

type ReactionActionData = Extract<EngagementAction, { kind: "reaction" }>;

export interface ReactionActionProps {
  action: ReactionActionData;
  variant: EngagementBarVariant;
  /** Shown state (`viewerReaction`, `reactionCounts`, `reactionTotalCount` are read). */
  state: EngagementState;
  /**
   * Select / clear path. The bar passes its `selectReaction` (gating, handler, optimistic
   * overlay); this part calls it microtask-deferred (Defense 1).
   */
  onSelect: (kind: string | null) => void;
  format: (n: number) => string;
  labels: ResolvedEngagementBarLabels;
  /** Direction for the picker's arrow keys + its portal content. Default `"ltr"`. */
  dir?: Direction;
  /** Fires when the picker opens / closes (changes only, plus a close on unmount while open). */
  onPickerOpenChange?: (open: boolean) => void;
  actionClassName?: string;
}

function ReactionActionInner({
  action,
  variant,
  state,
  onSelect,
  format,
  labels,
  dir = "ltr",
  onPickerOpenChange,
  actionClassName,
}: ReactionActionProps) {
  const [pickerOpen, setPickerOpen] = useState(false);

  // Report picker open / close to the host: on change only (never on mount), and a close if the
  // bar unmounts while the picker is up so a host's pause reason cannot stick.
  const onPickerOpenChangeRef = useRef(onPickerOpenChange);
  useEffect(() => {
    onPickerOpenChangeRef.current = onPickerOpenChange;
  });
  const reportedOpenRef = useRef(false);
  useEffect(() => {
    if (reportedOpenRef.current === pickerOpen) return;
    reportedOpenRef.current = pickerOpen;
    onPickerOpenChangeRef.current?.(pickerOpen);
  }, [pickerOpen]);
  useEffect(
    () => () => {
      if (reportedOpenRef.current) {
        reportedOpenRef.current = false;
        onPickerOpenChangeRef.current?.(false);
      }
    },
    [],
  );
  const disabled = !!action.disabled;

  // Long-press detection refs.
  const longPressTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const longPressFired = useRef(false);
  const downPos = useRef({ x: 0, y: 0 });

  const disabledRef = useRef(disabled);
  useEffect(() => {
    disabledRef.current = disabled;
  });

  const cancelLongPress = useCallback(() => {
    if (longPressTimer.current !== null) {
      clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  }, []);
  // A pending long-press must never fire after unmount.
  useEffect(() => cancelLongPress, [cancelLongPress]);

  // A pointer that left (scroll took over) leaves no long-press behind.
  const handlePointerCancel = useCallback(() => {
    cancelLongPress();
    longPressFired.current = false;
  }, [cancelLongPress]);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (disabled) return;
      // Only the main mouse button starts a long-press.
      if (e.pointerType === "mouse" && e.button !== 0) return;
      // A second pointer while one is pending (pinch, two fingers) is not a long-press:
      // cancel instead of leaving the first finger's timer running.
      if (longPressTimer.current !== null) {
        cancelLongPress();
        return;
      }
      // Capture so subsequent pointermove / pointerup events keep firing on
      // this button even if the user drags off. Without this, long-press would
      // continue running on a button the user has already left (per E7).
      try {
        e.currentTarget.setPointerCapture(e.pointerId);
      } catch {
        // Older browsers / non-pointer-capable inputs — silently degrade.
      }
      longPressFired.current = false;
      downPos.current = { x: e.clientX, y: e.clientY };
      longPressTimer.current = setTimeout(() => {
        longPressTimer.current = null;
        if (disabledRef.current) return;
        longPressFired.current = true;
        setPickerOpen(true);
      }, LONG_PRESS_MS);
    },
    [disabled, cancelLongPress],
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent<HTMLButtonElement>) => {
      if (longPressTimer.current === null) return;
      const dx = e.clientX - downPos.current.x;
      const dy = e.clientY - downPos.current.y;
      if (dx * dx + dy * dy > POINTER_MOVE_TOLERANCE_SQ) {
        cancelLongPress();
      }
    },
    [cancelLongPress],
  );

  // The trigger allows panning (`touch-manipulation`), so a long-press on touch can raise the
  // native context menu — suppress it only while a long-press is running or has just fired.
  const handleContextMenu = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
    if (longPressTimer.current !== null || longPressFired.current) e.preventDefault();
  }, []);

  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (open && disabled) return;
      setPickerOpen(open);
    },
    [disabled],
  );

  const handleIconClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
    // PopoverTrigger's built-in onClick fires alongside ours (Slot mergeProps
    // composes both handlers; Radix's `setOpen(!open)` toggle runs after our
    // handler returns). We override Radix's toggle via `queueMicrotask` when
    // our tap-matrix doesn't want it to fire — the microtask runs after Radix's
    // state update commits, so our `setPickerOpen(...)` is the final value.
    // This avoids the F-cross-13 mismatch (Base UI doesn't export PopoverAnchor)
    // while still suppressing Radix's auto-toggle when needed.
    if (disabled) {
      queueMicrotask(() => setPickerOpen(false));
      return;
    }

    // Long-press suppression: the timer already opened the picker. Radix's
    // trailing click would close it; force it back open.
    // A keyboard click (detail 0) never follows a long-press — ignore a stale flag.
    const fromLongPress = longPressFired.current && e.detail !== 0;
    longPressFired.current = false;
    if (fromLongPress) {
      queueMicrotask(() => setPickerOpen(true));
      return;
    }
    cancelLongPress();

    const viewer = state.viewerReaction;
    const clearOnTap = action.clearOnTap ?? true;

    // F-01 lock matrix:
    //   viewer = null  →  open picker (any clearOnTap) — Radix toggles for us
    //   viewer = set, clearOnTap = true  →  clear (microtask onSelect(null)) —
    //     Radix toggles open, we override to closed
    //   viewer = set, clearOnTap = false →  open picker — Radix toggles for us
    if (viewer !== null && clearOnTap) {
      // Defense 1 — microtask-deferred select + override Radix's auto-toggle.
      // Both queued in the same microtask for consistency.
      queueMicrotask(() => {
        onSelect(null);
        setPickerOpen(false);
      });
    }
    // Else: Radix's PopoverTrigger toggle handles opening the picker. We
    // don't call setPickerOpen here.
  }, [disabled, cancelLongPress, state.viewerReaction, action.clearOnTap, onSelect]);

  const handlePick = useCallback(
    (kind: string | null) => {
      setPickerOpen(false);
      if (kind === state.viewerReaction) return;
      // Defense 1 — microtask-deferred select.
      queueMicrotask(() => {
        onSelect(kind);
      });
    },
    [state.viewerReaction, onSelect],
  );

  // Resolve display values per Q-PP-5.
  const currentKind = action.kinds.find((k) => k.key === state.viewerReaction);
  const displayColor = currentKind?.color;
  const triggerLabel = currentKind?.label ?? labels.react;

  // Q-PP-5 visibility rule — count hides when withheld, or when total is 0 AND viewer is null.
  const totalCount = state.reactionTotalCount;
  const showCount =
    totalCount !== null && (totalCount > 0 || state.viewerReaction !== null);
  const splitCount = !!action.onCountClick;

  const triggerName = useActionName(showCount && !splitCount);
  const countName = useActionName(true);

  const iconSizeClass = variant === "compact" ? "h-4 w-4" : "h-5 w-5";

  // Icon node — viewer's current kind icon when set, neutral Smile otherwise.
  const iconNode = currentKind ? (
    <span
      aria-hidden="true"
      className={cn("flex items-center justify-center", iconSizeClass)}
      style={displayColor ? { color: displayColor } : undefined}
    >
      {currentKind.icon}
    </span>
  ) : (
    <Smile aria-hidden="true" className={cn(iconSizeClass, "motion-safe:transition-transform")} />
  );

  const countButton =
    splitCount && showCount ? (
      <button
        type="button"
        onClick={() => {
          if (disabled) return;
          action.onCountClick?.();
        }}
        aria-labelledby={countName.labelledBy}
        aria-disabled={disabled || undefined}
        className={cn(
          "rounded text-sm font-medium tabular-nums text-foreground motion-safe:transition-colors",
          "hover:underline focus:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          DISABLED_ACTION_CLASS,
        )}
      >
        <span id={countName.labelId} className="sr-only">
          {labels.openReactionsPanel}
        </span>
        <span id={countName.countId}>{format(totalCount)}</span>
      </button>
    ) : null;

  // F-cross-13 deeper: Base UI's PopoverTrigger doesn't accept `asChild` (it
  // uses a `render` prop pattern instead). Radix DOES accept asChild. Cross-
  // compatible solution: render PopoverTrigger DIRECTLY as the button (both
  // libraries render it as a `<button>` by default + pass through props).
  const popover = (
    <Popover open={pickerOpen} onOpenChange={handleOpenChange}>
      <PopoverTrigger
        type="button"
        aria-pressed={state.viewerReaction !== null}
        aria-labelledby={triggerName.labelledBy}
        aria-disabled={disabled || undefined}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={cancelLongPress}
        onPointerCancel={handlePointerCancel}
        onContextMenu={handleContextMenu}
        onClick={handleIconClick}
        className={cn(
          "inline-flex h-9 items-center gap-2 rounded-md px-2 text-sm font-medium motion-safe:transition-colors",
          "hover:bg-accent focus:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          // Pan + pinch stay available, so a swipe that starts here scrolls the page (EB5).
          "select-none touch-manipulation [-webkit-touch-callout:none]",
          state.viewerReaction !== null && "text-foreground",
          DISABLED_ACTION_CLASS,
          // E10 — non-split mode merges actionClassName into the trigger button.
          !splitCount && actionClassName,
        )}
      >
        {iconNode}
        <span id={triggerName.labelId} className="sr-only">
          {triggerLabel}
        </span>
        {showCount && !splitCount ? (
          <span
            id={triggerName.countId}
            className="text-sm font-medium tabular-nums"
            aria-live="polite"
          >
            {format(totalCount)}
          </span>
        ) : null}
      </PopoverTrigger>
      <PopoverContent
        className="w-auto"
        align="start"
        dir={dir}
        aria-label={labels.reactionPickerLabel}
      >
        <ReactionPicker
          kinds={action.kinds}
          mergedCounts={state.reactionCounts ?? {}}
          viewerReaction={state.viewerReaction}
          onSelect={handlePick}
          labels={labels}
          format={format}
          dir={dir}
        />
      </PopoverContent>
    </Popover>
  );

  // Variant layouts mirror like-action's structure.
  // E10 — non-split returns the popover bare (button carries actionClassName);
  // split wraps in an outer div with actionClassName to host both popover + countButton.
  if (variant === "stacked") {
    if (splitCount) {
      return (
        <div
          className={cn(
            "flex flex-col items-center gap-0.5",
            actionClassName,
          )}
        >
          {popover}
          {countButton}
        </div>
      );
    }
    return popover;
  }

  // default + compact horizontal.
  if (splitCount) {
    return (
      <div className={cn("flex items-center gap-2 pe-2", actionClassName)}>
        {popover}
        {countButton}
      </div>
    );
  }

  return popover;
}

export const ReactionAction = memo(ReactionActionInner);
ReactionAction.displayName = "ReactionAction";

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
} from "react";
import type {
  EngagementAction,
  EngagementCount,
  EngagementDelta,
  EngagementLocalAction,
  EngagementState,
  Subscribe,
} from "../types";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

interface ControlledFlags {
  liked: boolean;
  likeCount: boolean;
  bookmarked: boolean;
  /** comment / share / view-count follow their prop whenever the action is present. */
  commentCount: boolean;
  shareCount: boolean;
  viewCount: boolean;
  /** Controlled if `action.viewerReaction !== undefined` (string OR null). */
  viewerReaction: boolean;
  /** Paired with `viewerReaction`: a controlled reaction's `kinds[i].count` + `totalCount` win every render. */
  reactionCounts: boolean;
}

type Group = "like" | "bookmark" | "reaction";
type CountField = "commentCount" | "shareCount" | "viewCount";

interface PendingEntry {
  seq: number;
  patch: Partial<EngagementState>;
  /** The group's props when the request was made — a controlled entry is void once they change. */
  basis: string;
}
type PendingMap = Partial<Record<Group, PendingEntry>>;

interface DeltaOverride {
  value: number;
  /** The prop count when the delta arrived — the override shows until the prop changes. */
  basis: EngagementCount;
}
type OverrideMap = Partial<Record<CountField, DeltaOverride>>;

const GROUPS: Group[] = ["like", "bookmark", "reaction"];
const COUNT_FIELDS: CountField[] = ["commentCount", "shareCount", "viewCount"];
const COUNT_FIELD_KIND = {
  commentCount: "comment",
  shareCount: "share",
  viewCount: "view-count",
} as const;

const INITIAL_EMPTY_STATE: EngagementState = {
  liked: false,
  likeCount: null,
  commentCount: null,
  shareCount: null,
  viewCount: null,
  bookmarked: false,
  reactionCounts: null,
  reactionTotalCount: null,
  viewerReaction: null,
};

/** A count the host gave as a finite number, else withheld (`null`). Absent / NaN → withheld. */
function known(count: EngagementCount | undefined): EngagementCount {
  return typeof count === "number" && Number.isFinite(count) ? count : null;
}

/** A delta count must be a finite number; anything else keeps the current value. */
function sane(count: number, current: EngagementCount): EngagementCount {
  return Number.isFinite(count) ? Math.max(0, count) : current;
}

function step(count: EngagementCount | undefined, delta: 1 | -1): EngagementCount {
  if (count === null) return null;
  return Math.max(0, (count ?? 0) + delta);
}

function findAction<K extends EngagementAction["kind"]>(
  actions: EngagementAction[],
  kind: K,
): Extract<EngagementAction, { kind: K }> | undefined {
  return actions.find(
    (a): a is Extract<EngagementAction, { kind: K }> => a.kind === kind,
  );
}

/**
 * Pure derivation of the initial state shape from the actions array.
 * Each action contributes its initial values to the corresponding field;
 * absent actions use the default (null / false). Absent counts are withheld (`null`).
 */
export function deriveStateFromActions(
  actions: EngagementAction[],
): EngagementState {
  const next: EngagementState = { ...INITIAL_EMPTY_STATE };
  for (const action of actions) {
    switch (action.kind) {
      case "like":
        next.liked = action.liked ?? false;
        next.likeCount = known(action.count);
        break;
      case "comment":
        next.commentCount = known(action.count);
        break;
      case "share":
        next.shareCount = known(action.count);
        break;
      case "bookmark":
        next.bookmarked = action.bookmarked ?? false;
        break;
      case "view-count":
        next.viewCount = known(action.count);
        break;
      case "reaction":
        next.reactionCounts = action.kinds.reduce<Record<string, EngagementCount>>(
          (acc, k) => {
            acc[k.key] = known(k.count);
            return acc;
          },
          {},
        );
        next.reactionTotalCount = known(action.totalCount);
        next.viewerReaction = action.viewerReaction ?? null;
        break;
      // "custom" doesn't contribute to internal state — host owns active/count
    }
  }
  return next;
}

function deriveControlledFlags(actions: EngagementAction[]): ControlledFlags {
  const like = findAction(actions, "like");
  const bookmark = findAction(actions, "bookmark");
  const reaction = findAction(actions, "reaction");
  const likeControlled = like?.liked !== undefined;
  const reactionControlled = reaction !== undefined && reaction.viewerReaction !== undefined;
  return {
    liked: likeControlled,
    // Paired contract: the like count is controlled iff `liked` is.
    likeCount: likeControlled,
    bookmarked: bookmark?.bookmarked !== undefined,
    commentCount: findAction(actions, "comment") !== undefined,
    shareCount: findAction(actions, "share") !== undefined,
    viewCount: findAction(actions, "view-count") !== undefined,
    viewerReaction: reactionControlled,
    reactionCounts: reactionControlled,
  };
}

function isGroupControlled(group: Group, controlled: ControlledFlags): boolean {
  if (group === "like") return controlled.liked;
  if (group === "bookmark") return controlled.bookmarked;
  return controlled.viewerReaction;
}

/** A stable key of a group's props — a controlled optimistic value is void once it changes. */
function basisOf(group: Group, actions: EngagementAction[]): string {
  if (group === "like") {
    const a = findAction(actions, "like");
    return a ? `${String(a.liked)}|${String(known(a.count))}` : "";
  }
  if (group === "bookmark") {
    return String(findAction(actions, "bookmark")?.bookmarked);
  }
  const a = findAction(actions, "reaction");
  if (!a) return "";
  const kinds = a.kinds.map((k) => `${k.key}:${String(known(k.count))}`).join(",");
  return `${String(a.viewerReaction)}|${String(known(a.totalCount))}|${kinds}`;
}

function propCount(actions: EngagementAction[], field: CountField): EngagementCount {
  const action = actions.find((a) => a.kind === COUNT_FIELD_KIND[field]);
  if (!action || !("count" in action)) return null;
  return known(action.count);
}

/** Pure reducer — exported for hosts driving their own state. A `null` count stays `null`. */
export function engagementReducer(
  state: EngagementState,
  action: EngagementLocalAction,
): EngagementState {
  switch (action.kind) {
    case "like-toggle": {
      const nextLiked = !state.liked;
      return {
        ...state,
        liked: nextLiked,
        likeCount: step(state.likeCount, nextLiked ? 1 : -1),
      };
    }
    case "like-set": {
      if (state.liked === action.liked) return state;
      // A count the internal state never knew (seeded withheld) starts from the shown base.
      const from = state.likeCount ?? action.baseCount ?? null;
      return {
        ...state,
        liked: action.liked,
        likeCount: step(from, action.liked ? 1 : -1),
      };
    }
    case "bookmark-toggle":
      return { ...state, bookmarked: !state.bookmarked };
    case "bookmark-set":
      if (state.bookmarked === action.bookmarked) return state;
      return { ...state, bookmarked: action.bookmarked };
    case "subscribe-delta": {
      const d = action.delta;
      switch (d.kind) {
        case "like-changed":
          return {
            ...state,
            likeCount: sane(d.count, state.likeCount),
            liked: d.liked ?? state.liked,
          };
        case "comment-count-changed":
          return { ...state, commentCount: sane(d.count, state.commentCount) };
        case "share-count-changed":
          return { ...state, shareCount: sane(d.count, state.shareCount) };
        case "view-count-changed":
          return { ...state, viewCount: sane(d.count, state.viewCount) };
        case "bookmark-changed":
          return { ...state, bookmarked: d.bookmarked };
        case "liker-added":
        case "liker-removed":
          // These deltas inform the likersPreview slot host, not the bar's
          // internal state. Bar state unchanged.
          return state;
        case "reaction-changed":
          // Server-authoritative replace. Counts + total + viewer all swap to
          // the delta payload. Viewer is optional in the delta — fall back to
          // current state when absent (so the server can update just counts).
          return {
            ...state,
            reactionCounts: d.counts,
            reactionTotalCount: d.totalCount,
            viewerReaction:
              d.viewerReaction !== undefined
                ? d.viewerReaction
                : state.viewerReaction,
          };
        case "reactor-added":
        case "reactor-removed":
          // Pass-through per Q-PP-4 — the bar does not maintain a reactor list.
          // Hosts that want a live reactors strip consume the delta via
          // onSubscribeDelta and render into the `reactionsPreview` slot.
          return state;
      }
      return state;
    }
    case "reaction-select": {
      // Optimistic per-kind tally update. A null reactionKind clears the viewer
      // + decrements the old kind. Withheld (null) tallies stay withheld.
      const base = action.base;
      if (state.reactionCounts === null && !base) {
        // No reaction action present (and no shown base) — dispatch is a no-op.
        return state;
      }
      const current = state.viewerReaction;
      const next = action.reactionKind;
      if (current === next) return state; // same kind tap = no-op

      // Live internal tallies win; kinds the internal state never knew (added after mount,
      // or seeded withheld) start from the shown base.
      const counts: Record<string, EngagementCount> = { ...(base?.counts ?? {}) };
      for (const [key, value] of Object.entries(state.reactionCounts ?? {})) {
        if (value !== null && value !== undefined) counts[key] = value;
        else if (counts[key] === undefined || counts[key] === null) counts[key] = null;
      }
      let total = state.reactionTotalCount ?? base?.total ?? null;

      if (current !== null) {
        // Counts can never go below 0 (defensive — host backend should guarantee
        // this, but optimistic ops shouldn't crash on drift).
        counts[current] = step(counts[current], -1);
        total = step(total, -1);
      }
      if (next !== null) {
        counts[next] = step(counts[next], 1);
        total = step(total, 1);
      }
      return {
        ...state,
        reactionCounts: counts,
        reactionTotalCount: total,
        viewerReaction: next,
      };
    }
    case "reset":
      return action.next;
  }
}

function isControlledForDelta(
  delta: EngagementDelta,
  controlled: ControlledFlags,
): boolean {
  switch (delta.kind) {
    case "like-changed":
      return controlled.liked || controlled.likeCount;
    case "bookmark-changed":
      return controlled.bookmarked;
    case "reaction-changed":
      // Pair rule: a controlled reaction owns viewer + counts — the host applies the delta.
      return controlled.viewerReaction;
    case "comment-count-changed":
    case "share-count-changed":
    case "view-count-changed":
    case "liker-added":
    case "liker-removed":
    case "reactor-added":
    case "reactor-removed":
      // Count deltas also patch internal state (read when the action is absent); the shown
      // count comes from the delta overlay. The rest never patch internal state.
      return false;
  }
}

export interface UseEngagementStateOptions {
  actions: EngagementAction[];
  subscribe?: Subscribe<EngagementDelta>;
  onSubscribeDelta?: (delta: EngagementDelta) => void;
  /** See `EngagementBarProps.optimistic`. Default `true`. */
  optimistic?: boolean;
}

export interface UseEngagementStateResult {
  /** The shown state: props, optimistic and delta overlays applied. */
  state: EngagementState;
  dispatch: React.Dispatch<EngagementLocalAction>;
  controlled: ControlledFlags;
  /** Toggle like through the full path (gating, handler, optimistic, rollback). */
  toggleLike: () => void;
  /** Toggle bookmark through the full path. */
  toggleBookmark: () => void;
  /** Select (string) or clear (`null`) the viewer's reaction through the full path. Same kind = no-op. */
  selectReaction: (kind: string | null) => void;
  /** Re-seed internal state from the actions and drop optimistic / delta overlays. */
  reset: () => void;
}

/**
 * State for the bar:
 *  - useReducer over engagementReducer (uncontrolled fields)
 *  - per-render controlled-vs-uncontrolled flags; controlled props win per field, every render
 *  - optimistic overlay for promise-returning handlers (latest request decides, rejection rolls back)
 *  - delta overlay for comment / share / view counts (shows until the prop changes)
 *  - subscription effect that fires onSubscribeDelta and patches uncontrolled fields
 */
export function useEngagementState(
  opts: UseEngagementStateOptions,
): UseEngagementStateResult {
  const { actions } = opts;
  const initial = useMemo(
    () => deriveStateFromActions(actions),
    // intentionally only on mount — useReducer ignores initial changes after mount,
    // but we still memoize so the closure is stable.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );
  const [internalState, dispatch] = useReducer(engagementReducer, initial);
  const [pending, setPending] = useState<PendingMap>({});
  const [overrides, setOverrides] = useState<OverrideMap>({});

  const controlled = useMemo(() => deriveControlledFlags(actions), [actions]);

  // Shown state: controlled props win per field, then valid overlays, then withheld counts.
  const state = useMemo<EngagementState>(() => {
    const like = findAction(actions, "like");
    const bookmark = findAction(actions, "bookmark");
    const reaction = findAction(actions, "reaction");

    const overlaid = (field: CountField, prop: EngagementCount): EngagementCount => {
      if (prop === null) return null;
      const o = overrides[field];
      return o && o.basis === prop ? o.value : prop;
    };
    const countFor = (field: CountField, kind: (typeof COUNT_FIELD_KIND)[CountField]) =>
      actions.some((a) => a.kind === kind)
        ? overlaid(field, propCount(actions, field))
        : internalState[field];

    const likeProp = like ? known(like.count) : null;
    const totalProp = reaction ? known(reaction.totalCount) : null;

    const shown: EngagementState = {
      liked: controlled.liked && like ? (like.liked ?? false) : internalState.liked,
      likeCount: like
        ? likeProp === null
          ? null
          : controlled.likeCount
            ? likeProp
            : (internalState.likeCount ?? likeProp)
        : internalState.likeCount,
      commentCount: countFor("commentCount", "comment"),
      shareCount: countFor("shareCount", "share"),
      viewCount: countFor("viewCount", "view-count"),
      bookmarked:
        controlled.bookmarked && bookmark
          ? (bookmark.bookmarked ?? false)
          : internalState.bookmarked,
      reactionCounts: reaction
        ? reaction.kinds.reduce<Record<string, EngagementCount>>((acc, k) => {
            const p = known(k.count);
            acc[k.key] =
              p === null
                ? null
                : controlled.reactionCounts
                  ? p
                  : (internalState.reactionCounts?.[k.key] ?? p);
            return acc;
          }, {})
        : internalState.reactionCounts,
      reactionTotalCount: reaction
        ? totalProp === null
          ? null
          : controlled.reactionCounts
            ? totalProp
            : (internalState.reactionTotalCount ?? totalProp)
        : internalState.reactionTotalCount,
      viewerReaction:
        controlled.viewerReaction && reaction
          ? (reaction.viewerReaction ?? null)
          : internalState.viewerReaction,
    };

    for (const group of GROUPS) {
      const entry = pending[group];
      if (!entry) continue;
      if (isGroupControlled(group, controlled) && entry.basis !== basisOf(group, actions)) continue;
      Object.assign(shown, entry.patch);
    }

    // A withheld count stays withheld through every overlay (C6).
    if (like && likeProp === null) shown.likeCount = null;
    if (reaction) {
      if (totalProp === null) shown.reactionTotalCount = null;
      if (shown.reactionCounts) {
        const counts = { ...shown.reactionCounts };
        for (const k of reaction.kinds) if (known(k.count) === null) counts[k.key] = null;
        shown.reactionCounts = counts;
      }
    }
    return shown;
  }, [internalState, actions, controlled, pending, overrides]);

  // Refs read by the request functions + the subscription (latest committed values).
  const shownRef = useRef(state);
  const actionsRef = useRef(actions);
  const controlledRef = useRef(controlled);
  const optimisticRef = useRef(opts.optimistic ?? true);
  const onSubscribeDeltaRef = useRef(opts.onSubscribeDelta);
  useIsoLayoutEffect(() => {
    shownRef.current = state;
    actionsRef.current = actions;
    controlledRef.current = controlled;
    optimisticRef.current = opts.optimistic ?? true;
    onSubscribeDeltaRef.current = opts.onSubscribeDelta;
  });

  // Drop overlays whose basis is gone, so a prop that changes A → B → A can't revive them.
  // React's "adjust state when a prop changes" pattern (a guarded setState during render):
  // when the props' basis changes, drop every overlay made against an older basis.
  const basisKey = [
    ...GROUPS.map((group) => basisOf(group, actions)),
    ...COUNT_FIELDS.map((field) => String(propCount(actions, field))),
  ].join("§");
  const [seenBasisKey, setSeenBasisKey] = useState(basisKey);
  if (seenBasisKey !== basisKey) {
    setSeenBasisKey(basisKey);
    const stalePending = GROUPS.filter((group) => {
      const entry = pending[group];
      return !!entry && isGroupControlled(group, controlled) && entry.basis !== basisOf(group, actions);
    });
    if (stalePending.length > 0) {
      setPending((p) => {
        const next = { ...p };
        for (const group of stalePending) delete next[group];
        return next;
      });
    }
    const staleOverrides = COUNT_FIELDS.filter((field) => {
      const entry = overrides[field];
      return !!entry && entry.basis !== propCount(actions, field);
    });
    if (staleOverrides.length > 0) {
      setOverrides((o) => {
        const next = { ...o };
        for (const field of staleOverrides) delete next[field];
        return next;
      });
    }
  }

  const seqRef = useRef<Record<Group, number>>({ like: 0, bookmark: 0, reaction: 0 });
  const settledRef = useRef<Record<Group, number>>({ like: 0, bookmark: 0, reaction: 0 });

  const clearPending = useCallback((group: Group, id: number) => {
    setPending((p) => {
      if (p[group]?.seq !== id) return p;
      const next = { ...p };
      delete next[group];
      return next;
    });
  }, []);

  // One request path for like / bookmark / reaction (C5 semantics of the scaffold's
  // use-controllable-state): sync handler → uncontrolled applies, controlled waits for props;
  // promise → optimistic overlay until it settles; only the latest request decides.
  const run = useCallback(
    (group: Group, patch: Partial<EngagementState>, call: () => unknown, apply: () => void) => {
      const id = ++seqRef.current[group];
      const isControlled = isGroupControlled(group, controlledRef.current);
      const basis = basisOf(group, actionsRef.current);
      const dropPending = () =>
        setPending((p) => {
          if (!p[group]) return p;
          const next = { ...p };
          delete next[group];
          return next;
        });
      let result: unknown;
      try {
        result = call();
      } catch (error) {
        // A throwing handler is a host bug — never leave an older request's overlay stuck.
        dropPending();
        throw error;
      }
      const isPromise =
        !!result && typeof (result as PromiseLike<unknown>).then === "function";
      if (!isPromise) {
        // This request is now the latest: an older in-flight overlay must not outlive it.
        dropPending();
        if (!isControlled) {
          settledRef.current[group] = id;
          apply();
        }
        return;
      }
      if (optimisticRef.current) {
        setPending((p) => ({ ...p, [group]: { seq: id, patch, basis } }));
      }
      (result as PromiseLike<unknown>).then(
        () => {
          if (!isControlled && id > settledRef.current[group]) {
            settledRef.current[group] = id;
            apply();
          }
          if (id === seqRef.current[group]) clearPending(group, id);
        },
        () => {
          if (id === seqRef.current[group]) clearPending(group, id);
        },
      );
    },
    [clearPending],
  );

  const toggleLike = useCallback(() => {
    const action = findAction(actionsRef.current, "like");
    if (!action || action.disabled || action.hidden) return;
    const shown = shownRef.current;
    const target = !shown.liked;
    run(
      "like",
      { liked: target, likeCount: step(shown.likeCount, target ? 1 : -1) },
      () => action.onToggle?.(target),
      () => dispatch({ kind: "like-set", liked: target, baseCount: shown.likeCount }),
    );
  }, [run]);

  const toggleBookmark = useCallback(() => {
    const action = findAction(actionsRef.current, "bookmark");
    if (!action || action.disabled || action.hidden) return;
    const target = !shownRef.current.bookmarked;
    run(
      "bookmark",
      { bookmarked: target },
      () => action.onToggle?.(target),
      () => dispatch({ kind: "bookmark-set", bookmarked: target }),
    );
  }, [run]);

  const selectReaction = useCallback(
    (kind: string | null) => {
      const action = findAction(actionsRef.current, "reaction");
      if (!action || action.disabled || action.hidden) return;
      if (kind !== null && !action.kinds.some((k) => k.key === kind)) return;
      const shown = shownRef.current;
      if (kind === shown.viewerReaction) return;
      const next = engagementReducer(shown, { kind: "reaction-select", reactionKind: kind });
      run(
        "reaction",
        {
          viewerReaction: next.viewerReaction,
          reactionCounts: next.reactionCounts,
          reactionTotalCount: next.reactionTotalCount,
        },
        () => action.onSelect?.(kind),
        () =>
          dispatch({
            kind: "reaction-select",
            reactionKind: kind,
            base: { counts: shown.reactionCounts ?? {}, total: shown.reactionTotalCount },
          }),
      );
    },
    [run],
  );

  const reset = useCallback(() => {
    // In-flight requests may still settle — they must not re-apply over the reset.
    for (const group of GROUPS) settledRef.current[group] = seqRef.current[group];
    setPending({});
    setOverrides({});
    dispatch({ kind: "reset", next: deriveStateFromActions(actionsRef.current) });
  }, []);

  // Subscription — stable on `subscribe` identity only. Re-running it on `controlled` or
  // `onSubscribeDelta` change would drop deltas in flight between cleanup + re-call.
  const subscribe = opts.subscribe;
  useEffect(() => {
    if (!subscribe) return;
    const unsub = subscribe((delta) => {
      onSubscribeDeltaRef.current?.(delta);
      const field: CountField | null =
        delta.kind === "comment-count-changed"
          ? "commentCount"
          : delta.kind === "share-count-changed"
            ? "shareCount"
            : delta.kind === "view-count-changed"
              ? "viewCount"
              : null;
      if (field && "count" in delta && Number.isFinite(delta.count)) {
        const value = Math.max(0, delta.count);
        const basis = propCount(actionsRef.current, field);
        setOverrides((o) => ({ ...o, [field]: { value, basis } }));
      }
      if (!isControlledForDelta(delta, controlledRef.current)) {
        dispatch({ kind: "subscribe-delta", delta });
      }
    });
    return unsub;
  }, [subscribe]);

  // Defense 2 (structural resync guard) per Q-PP-3 — when the host transitions
  // `viewerReaction` from uncontrolled → controlled (or changes the controlled
  // value), keep the internal mirror in step so a later switch back to
  // uncontrolled resumes from the last controlled value.
  const reactionAction = findAction(actions, "reaction");
  const controlledViewerReaction =
    controlled.viewerReaction && reactionAction
      ? (reactionAction.viewerReaction ?? null)
      : undefined;
  const internalStateRef = useRef(internalState);
  useEffect(() => {
    internalStateRef.current = internalState;
  });
  useEffect(() => {
    if (controlledViewerReaction === undefined) return;
    const current = internalStateRef.current;
    if (controlledViewerReaction === current.viewerReaction) return;
    dispatch({
      kind: "reset",
      next: { ...current, viewerReaction: controlledViewerReaction },
    });
  }, [controlledViewerReaction]);

  return { state, dispatch, controlled, toggleLike, toggleBookmark, selectReaction, reset };
}

/**
 * Compact, locale-aware engagement count:
 *   formatEngagementCount(999)          → "999"
 *   formatEngagementCount(1_234)        → "1.2K"
 *   formatEngagementCount(12_345)       → "12K"
 *   formatEngagementCount(1_234_567)    → "1.2M"
 *   formatEngagementCount(1_200, "tr")  → "1,2 B"
 *
 * `Intl.NumberFormat(locale, { notation: "compact" })`. Negative values render as 0; a non-finite
 * value renders as "". The bar memoises its own formatter on `locale` — this helper builds one per
 * call, for hosts formatting a count outside the bar.
 */
export function formatEngagementCount(n: number, locale = "en"): string {
  if (!Number.isFinite(n)) return "";
  return new Intl.NumberFormat(resolveLocale(locale), { notation: "compact" }).format(Math.max(0, n));
}

/**
 * A valid BCP 47 tag for `locale`, else `"en"`. An invalid tag (`"en_US"` from an i18n library)
 * makes `Intl` and `toLocale*Case` throw — that must not take down the render.
 */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return "en";
  try {
    return Intl.getCanonicalLocales(locale)[0] ?? "en";
  } catch {
    return "en";
  }
}

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

import { useId } from "react";

/**
 * Accessible name = the action's label + its visible count ("Like 12"), so the visible count is
 * part of the name (WCAG 2.5.3) and a withheld count is never in it (C6). `aria-labelledby`
 * joins the two ids with a space; the label renders as visually-hidden text.
 */
export function useActionName(hasCount: boolean) {
  const id = useId();
  const labelId = `${id}-label`;
  const countId = `${id}-count`;
  return {
    labelId,
    countId,
    labelledBy: hasCount ? `${labelId} ${countId}` : labelId,
  };
}

/** Disabled actions stay focusable (`aria-disabled`) and look inert. */
export const DISABLED_ACTION_CLASS =
  "aria-disabled:cursor-not-allowed aria-disabled:opacity-50";
